CREATE FUNCTION chk_k5() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  IF (NEW.c3 IS NOT NULL AND NEW.c4 IS NOT NULL AND NEW.c6 IS NOT NULL AND NEW.c7 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c3 IS NOT NULL AND c4 IS NOT NULL AND c6 IS NOT NULL AND c7 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3 AND c4=NEW.c4 AND c6=NEW.c6 AND c7=NEW.c7) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c4 IS NOT NULL AND c6 IS NOT NULL AND c7 IS NOT NULL AND c0=NEW.c0 AND c4=NEW.c4 AND c6=NEW.c6 AND c7=NEW.c7) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c7 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3 AND c6=NEW.c6 AND c7=NEW.c7) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c3 IS NOT NULL AND c4 IS NOT NULL AND c7 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3 AND c4=NEW.c4 AND c7=NEW.c7) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c7 IS NULL AND c3 IS NOT NULL AND c4 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3 AND c4=NEW.c4 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c4 IS NULL AND c6 IS NOT NULL AND c7 IS NOT NULL AND c0=NEW.c0 AND c6=NEW.c6 AND c7=NEW.c7) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c6 IS NULL AND c4 IS NOT NULL AND c7 IS NOT NULL AND c0=NEW.c0 AND c4=NEW.c4 AND c7=NEW.c7) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c7 IS NULL AND c4 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c4=NEW.c4 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c6 IS NULL AND c3 IS NOT NULL AND c7 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3 AND c7=NEW.c7) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c7 IS NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3 AND 